import { LocalStorage } from '@game-studio/utilities';
import { Network } from './network';
import { PageVisibility } from './visibility';
import { VirtualKeyboard } from './virtual-keyboard';
import { Viewport } from './viewport';
import { DeviceOrientation } from './device-orientation';
import { DeviceInfo } from './device-info';
import { DeviceType } from './device-info/device-type';
import { DeviceModel } from './device-info/device-model';
import { cookiesEnabled } from './features/cookie-check';
import { supportsTouchEvents } from './features/touch-events-check';
import { supportsWebSockets } from './features/web-sockets';
import { supportsHistoryApi } from './features/history-api';
import { supportsWebGL } from './features/webgl-detection';
import { DeviceOptions, IDeviceFeatures, IDevicePlatform } from './types';
import { getDeviceId } from './device-id';
import { createDeviceTypeCode } from './device-info/device-type-code';
import { userAgent } from './user-agent';

export class Device {
    public readonly info: DeviceInfo = new DeviceInfo();
    public readonly model: DeviceModel = new DeviceModel();
    public readonly type: DeviceType;
    public readonly network: Network;
    public readonly visibility: PageVisibility;
    public readonly keyboard: VirtualKeyboard;
    public readonly orientation: DeviceOrientation;
    public readonly viewport: Viewport;
    public readonly deviceID: string;
    /**
     * @satisfies typeCode can be overwritten somewhere in the shell (not entirely sure why, otherwise this would be a readonly)
     */
    public typeCode: string;

    public get features(): IDeviceFeatures {
        return {
            localStorageEnabled: LocalStorage.isAvailable,
            cookiesEnabled: cookiesEnabled(),
            supportsTouchEvents: supportsTouchEvents(),
            supportsWebSockets: supportsWebSockets(),
            supportsWebGL: supportsWebGL(),
            supportsHistoryApi: supportsHistoryApi()
        };
    }

    public get platform(): IDevicePlatform {
        return this.type.isApp ? 'app' : 'web';
    }

    public static get userAgent() {
        return userAgent;
    }

    public constructor(options: Partial<DeviceOptions> = {}) {
        this.type = new DeviceType(options.forceType);
        this.deviceID = getDeviceId();
        this.network = new Network(this.type);
        this.visibility = new PageVisibility();
        this.keyboard = new VirtualKeyboard(this.type, this.info, options.freezePageDimensions !== undefined ? options.freezePageDimensions : true);
        this.orientation = new DeviceOrientation(this.type, this.info, this.keyboard, this.visibility, options);
        this.viewport = new Viewport(this.type, this.orientation, this.keyboard);
        this.typeCode = createDeviceTypeCode(this);
    }

    public toJSON() {
        return {
            platform: this.platform,
            deviceId: this.deviceID,
            typeCode: this.typeCode,
            type: this.type.value,
            model: this.model.model,
            vendor: this.model.vendor,
            browser: {
                name: this.info.browser.name,
                version: this.info.browser.version
            },
            operatingSystem: {
                name: this.info.operatingSystem.name,
                version: this.info.operatingSystem.version
            },
            features: {
                cookiesEnabled: this.features.cookiesEnabled,
                localStorageEnabled: this.features.localStorageEnabled,
                supportsHistoryApi: this.features.supportsHistoryApi,
                supportsTouchEvents: this.features.supportsTouchEvents,
                supportsWebGL: this.features.supportsWebGL,
                supportsWebSockets: this.features.supportsWebSockets
            },
            viewport: {
                width: this.viewport.width,
                height: this.viewport.height,
                trueWidth: this.viewport.trueWidth,
                trueHeight: this.viewport.trueHeight,
                isRetina: this.viewport.isRetina,
                pixelRatio: this.viewport.pixelRatio,
                safeAreas: this.viewport.safeAreas,
                notchHeight: 0
            },
            network: {
                isConnected: this.network.isConnected
            },
            orientation: {
                isInverted: this.orientation.isInverted,
                isLandscape: this.orientation.isLandscape,
                isPortrait: this.orientation.isPortrait,
                value: this.orientation.value,
                isChanging: this.orientation.isChanging
            },
            virtualKeyboard: {
                height: 0,
                isOpen: this.keyboard.isOpen
            },
            visibility: {
                isVisible: this.visibility.isVisible
            },
            isApp: this.type.isApp,
            isMobile: this.type.isMobile,
            isTablet: this.type.isTablet,
            isDesktop: this.type.isDesktop,
            isIphoneX: DeviceType.isIphoneX,
            isKindle: DeviceType.isKindle,
            isFoldable: this.type.isFoldable
        };
    }
}
